 "watch.wait":["seconds"], "watch.bell":["npc_id"],
 "watch.wake":["npc_id"], "watch.requested":["actor_id","npc_id"], "watch.echo":["npc_id","remaining"],
 "watch.npc-acted":["npc_id","before_bells","after_bells"],
 "watch.bell-rung":["actor_id","npc_id"], "watch.replied":["npc_id","before_count","after_count"],
 "watch.npc-cue":["npc_id","logical_tick","before_bells","after_bells","cell","x_mm","z_mm"],
 "watch.bell-cue":["actor_id","npc_id","logical_tick"],
 "watch.reply-cue":["npc_id","logical_tick","before_count","after_count"],
 "watch.charge-delta":["entity_id","before_charge","after_charge"], "watch.charge-patch":["charge"],
 "watch.bells-delta":["entity_id","before_bells","after_bells"], "watch.bells-patch":["bells"],
 "watch.reply-delta":["entity_id","before_count","after_count"], "watch.reply-patch":["count"],
}
