schema_document["components"] += [
 {"schema":key("watch.lantern"),"fields":{"charge":field("watch.passive","charge",0,3)}},
 {"schema":key("watch.npc"),"fields":{"space_id":field("system.bootstrap","entity_id"),
  "cell":field("system.bootstrap","cell",6,6),"bells":field("watch.npc","count",0,MAX)}},
 {"schema":key("watch.reply"),"fields":{"count":field("watch.echo","count",0,MAX)}},
]
schema_document["payloads"] += [{"schema":key(k),"fields":v} for k,v in new_fields.items()]
schema_document["payloads"].sort(key=lambda x:x["schema"]["kind"])
schema_document["system"]={"clock_owner":"system.clock","queue_owner":"system.events","pending_format":"queued-event/v1"}

def policy(kind,mode,phase,priority,producers,subscribers):
 return {"schema":key(kind),"mode":mode,"delivery_phase":phase,"priority":priority,
  "late_route":"reject","producers":sorted(producers),"subscribers":sorted(subscribers),"cancellers":[]}
policies=[]
for k in ("attack-resolved","defeated","gate-changed","move-blocked","moved","rested"):
 policies.append(policy("encounter."+k,"record_only","PRESENT",0,
  ["trial.movement" if k in ("move-blocked","moved") else "encounter.actions"],[]))
policies += [
 policy("watch.wake","simulate","PRE_TICK",10,["watch.npc"],["watch.npc"]),
 policy("watch.requested","simulate","REACT",20,["watch.bell"],["watch.respond"]),
 policy("watch.echo","simulate","CASCADE",30,["watch.respond","watch.echo"],["watch.echo"]),
 policy("watch.npc-acted","record_only","PRESENT",0,["watch.npc"],[]),
 policy("watch.bell-rung","record_only","PRESENT",0,["watch.bell"],[]),
 policy("watch.replied","record_only","PRESENT",0,["watch.echo"],[]),
]
policies.sort(key=lambda p:p["schema"]["kind"])
rules_document={"version":1,"encounter":copy.deepcopy(rules_document),"npc_id":NPC,"npc_cell":6,
 "npc_nonblocking":True,"lantern_id":LANTERN,"wake_period_seconds":2,"wake_epoch_tick":0,
 "initial_charge":0,"charge_max":3,"charge_per_second":1,"initial_bells":0,"initial_replies":0,
 "bell_duration_seconds":1,"bell_range":"same_space","echo_initial_remaining":1,
 "execution":{"enable_simulation":True,"max_duration_seconds":16,"cascade_waves":8,
  "max_events_per_tick":512,"max_pending":4096},"event_policies":policies,"rng_purposes":[],
 "pending_leaf_projection":["event_id","hash"],"hash_pending_tag":"pending-event/v1",
 "publication_facts":"all_new_emissions_including_simulation","no_idle_skip":True}

def wnode(engine,phase,reads,writes,kinds,emits,consumes=(),matching=False,every=False):
 return {"phase":phase,"engine_id":engine,"lane":"A","reads":sorted(reads),"writes":sorted(writes),
  "depends_on":[],"action_kinds":[key(k) for k in sorted(kinds)],"on_matching_events":matching,
  "every_tick":every,"emits":[key(k) for k in sorted(emits)],"consumes":[key(k) for k in sorted(consumes)],"cost_class":"local"}
schedule_document={"version":1,"nodes":[
 wnode("watch.npc","PRE_TICK",["watch.npc.bells","watch.npc.cell","watch.npc.space_id"],["watch.npc.bells"],[],["watch.npc-acted","watch.wake"],["watch.wake"],True),
 *copy.deepcopy(schedule_document["nodes"]),
 wnode("watch.bell","RESOLVE",["encounter.hp.hp","trial.position.space_id","watch.npc.cell","watch.npc.space_id"],[],["watch.bell"],["watch.bell-rung","watch.requested"]),
 wnode("watch.respond","REACT",[],[],[],["watch.echo"],["watch.requested"],True),
 wnode("watch.echo","CASCADE",["watch.reply.count"],["watch.reply.count"],[],["watch.echo","watch.replied"],["watch.echo"],True),
 wnode("watch.passive","POST_TICK",["watch.lantern.charge"],["watch.lantern.charge"],[],[],[],False,True),
]}
SCHEMA,RULES,SCHEDULE=(tagged(t,d) for t,d in (("schema/v1",schema_document),("rules/v1",rules_document),("schedule/v1",schedule_document)))
WORLD="w1-"+hashlib.sha256(frame("world-id/v1",SEED,RULES,CATALOG)).hexdigest()
pins={"schema_fingerprint":SCHEMA,"rules_fingerprint":RULES,"schedule_fingerprint":SCHEDULE,
 "rng_version":"sha256-counter-v1","hash_version":"sha256-core-tree-v1","gameplay_catalog_hash":CATALOG,"gameplay_packages":[]}
RANK={n["engine_id"]:i for i,n in enumerate(schedule_document["nodes"])}
PHASE={"PRE_TICK":1,"RESOLVE":2,"REACT":3,"CASCADE":4,"POST_TICK":5,"PRESENT":7}

def envelope(tick,phase,wave,producer,seq,kind,body,due=None,causes=()):
 identifier="e1-"+hashlib.sha256(frame("event-id/v1",WORLD,str(tick),phase,str(wave),producer,str(seq))).hexdigest()
 return {"header":{"event_id":identifier,"type_key":key(kind),"producer_id":producer,
  "occurred_at":tick,"phase":phase,"wave":wave,"producer_rank":RANK[producer],"sequence":seq,
  "caused_by":sorted(causes),"degraded":[]},"due_tick":tick if due is None else due,"payload":body}

def event(tick,kind,body,producer,sequence):
 return envelope(tick,"RESOLVE",0,producer,sequence,kind,body)

def queued(event):
 return {"event":copy.deepcopy(event),"delivery_phase":"PRE_TICK","priority":10}

def queue_order(q):
 h=q["event"]["header"]
 return (q["event"]["due_tick"],PHASE[q["delivery_phase"]],q["priority"],h["occurred_at"],PHASE[h["phase"]],h["wave"],h["producer_rank"],h["sequence"],h["event_id"])

def components(s):
 return _encounter_components(s)+[
  {"schema":key("watch.lantern"),"entity_id":LANTERN,"fields":{"charge":s["charge"]}},
  {"schema":key("watch.npc"),"entity_id":NPC,"fields":{"space_id":SPACE,"cell":6,"bells":s["bells"]}},
  {"schema":key("watch.reply"),"entity_id":NPC,"fields":{"count":s["replies"]}},
 ]

def core(s,tick,pending):
 return {"world_id":WORLD,"world_seed_hex":SEED,"tick":tick,"components":components(s),
  "pending":copy.deepcopy(sorted(pending,key=queue_order)),"pins":pins}

def core_hash(doc):
 leaves=[{"schema":c["schema"],"entity_id":c["entity_id"],"hash":tagged("component/v1",c)} for c in doc["components"]]
 events=[{"event_id":q["event"]["header"]["event_id"],"hash":tagged("pending-event/v1",q)} for q in doc["pending"]]
 return tagged("core-root/v1",{**doc,"components":leaves,"pending":events})

INITIAL={"cell":0,"gate":0,"actor_hp":3,"enemy_hp":5,"stamina":2,"bells":0,"charge":0,"replies":0}
GENESIS=queued(envelope(0,"PRE_TICK",0,"watch.npc",0,"watch.wake",{"npc_id":NPC},2))

def passive(s,pending,start,end):
 facts=[]
 for tick in range(start+1,end+1):
  if pending and pending[0]["event"]["due_tick"]==tick:
   wake=pending.pop(0)["event"];cause=(wake["header"]["event_id"],)
   old=s["bells"];s["bells"]+=1
   acted=envelope(tick,"PRE_TICK",0,"watch.npc",0,"watch.npc-acted",{"npc_id":NPC,"before_bells":old,"after_bells":s["bells"]},causes=cause)
