 for f in facts:
  kind=f["header"]["type_key"]["kind"];b=f["payload"];tick=f["header"]["occurred_at"]
  if kind=="watch.npc-acted":
   ck="watch.npc-cue";body={**b,"logical_tick":tick,"cell":6,"x_mm":0,"z_mm":2000}
  elif kind=="watch.bell-rung":ck="watch.bell-cue";body={**b,"logical_tick":tick}
