def resolve_watch(s,pending,cmd,start):
 old=copy.deepcopy(s);kind=cmd["schema"]["kind"];p=cmd["payload"]
 target=start+(p["seconds"] if kind=="watch.wait" else 1)
 facts=[]
 # Passive PRE_TICK and POST_TICK calculations commute only because the demo
 # does not change encounter state. Publish in actual tick/phase order below.
 facts.extend(passive(s,pending,start,target))
 changes=[]
 if kind=="watch.bell":
  request=envelope(target,"RESOLVE",0,"watch.bell",0,"watch.requested",{"actor_id":ACTOR,"npc_id":NPC})
  rung=envelope(target,"RESOLVE",0,"watch.bell",1,"watch.bell-rung",{"actor_id":ACTOR,"npc_id":NPC})
  echo1=envelope(target,"REACT",0,"watch.respond",0,"watch.echo",{"npc_id":NPC,"remaining":1},causes=(request["header"]["event_id"],))
  echo0=envelope(target,"CASCADE",0,"watch.echo",0,"watch.echo",{"npc_id":NPC,"remaining":0},causes=(echo1["header"]["event_id"],))
  s["replies"]+=1
  reply=envelope(target,"CASCADE",1,"watch.echo",0,"watch.replied",{"npc_id":NPC,"before_count":old["replies"],"after_count":s["replies"]},causes=(echo0["header"]["event_id"],))
  facts.extend((request,rung,echo1,echo0,reply))
 elif kind!="watch.wait":
  more,changes=_encounter_resolve(s,cmd,target);facts.extend(more)
 for name,kind,entity,before_key,after_key in (
  ("charge","watch.charge-delta",LANTERN,"before_charge","after_charge"),
  ("bells","watch.bells-delta",NPC,"before_bells","after_bells"),
  ("replies","watch.reply-delta",NPC,"before_count","after_count")):
  if old[name]!=s[name]:changes.append({"schema":key(kind),"entity_id":entity,before_key:old[name],after_key:s[name]})
 families={"watch.charge-delta":("watch.lantern","charge"),"watch.bells-delta":("watch.npc","bells"),"watch.reply-delta":("watch.reply","count"),
  "trial.position-delta":("trial.position","cell"),"encounter.gate-delta":("encounter.gate","is_open"),"encounter.hp-delta":("encounter.hp","hp"),"encounter.stamina-delta":("encounter.stamina","value")}
 changes.sort(key=lambda d:(*families[d["schema"]["kind"]],d["entity_id"]))
 facts.sort(key=lambda f:(f["header"]["occurred_at"],PHASE[f["header"]["phase"]],f["header"]["wave"],f["header"]["producer_rank"],f["header"]["sequence"]))
 return target,facts,changes

def trace_watch(flow,initial=None):
 s=copy.deepcopy(INITIAL if initial is None else initial);pending=[copy.deepcopy(GENESIS)]
 tick=revision=high_water=0;receipts=[]
 def protocol():
  return {"branch_id":BRANCH,"revision":revision,"streams":[{"stream_id":STREAM,"actor_id":ACTOR,"highest_committed_sequence":high_water,"status":"active"}],"receipts":copy.deepcopy(receipts)}
 initial_core,initial_protocol=core(s,0,pending),protocol()
 header={"world_id":WORLD,"world_seed_hex":SEED,"initial_core_hash":core_hash(initial_core),"initial_protocol_hash":tagged("protocol/v1",initial_protocol),
  "schema_fingerprint":SCHEMA,"rules_fingerprint":RULES,"schedule_fingerprint":SCHEDULE,"rng_version":pins["rng_version"],"hash_version":pins["hash_version"],"gameplay_packages":[],"build_artifacts":[]}
 steps=[];pubs=[];summary=[]
 for cmd in flow:
  facts=[];diff=None;cues=[];diagnostics=[];code=None
  seq=int(cmd["command_id"].split(":")[-1]);fp=tagged("command/v1",{k:v for k,v in cmd.items() if k!="command_id"})
  prior=next((r for r in receipts if r["command"]["command_id"]==cmd["command_id"]),None)
  if prior:
   if prior["command"]!=cmd:code="COMMAND_ID_CONFLICT"
   else:
    outcome={"kind":"committed","receipt":copy.deepcopy(prior["receipt"])}
    if prior["receipt"]["revision"]<revision:diagnostics=[{"code":"RESYNC_REQUIRED","message_key":"error.resync_required"}]
  elif seq<=high_water:code="RETRY_WINDOW_EXPIRED"
  elif cmd["expected_revision"]!=revision:code="STALE_REVISION"
  else:
   kind,p=cmd["schema"]["kind"],cmd["payload"]
   code=admission(s,kind,p)
   if code is None and kind=="watch.bell" and p["npc_id"]!=NPC:code="INVALID_TARGET"
   if code is None:
    oldrev=revision;tick,facts,changes=resolve_watch(s,pending,cmd,tick);revision+=1;high_water=seq
    receipt={"command_id":cmd["command_id"],"previous_revision":oldrev,"revision":revision,"tick":tick,"core_hash":core_hash(core(s,tick,pending))}
    outcome={"kind":"committed","receipt":receipt};diff={"receipt":receipt,"changes":changes}
    receipts.append({"command":copy.deepcopy(cmd),"command_fingerprint":fp,"receipt":receipt})
    cues=watch_cues(facts,s,tick)
  if code:outcome={"kind":"rejected","failure":{"code":code,"message_key":"error."+code.lower()},"current_revision":revision}
  cd,pd=core(s,tick,pending),protocol()
  steps.append({"command":copy.deepcopy(cmd),"outcome":copy.deepcopy(outcome),"core_hash":core_hash(cd),"protocol_hash":tagged("protocol/v1",pd),
   "facts_hash":tagged("turn-facts/v1",facts),"diff_hash":tagged("turn-diff/v1",diff),"witness":{"core":cd,"protocol":pd,"facts":copy.deepcopy(facts),"diff":copy.deepcopy(diff)}})
  pubs.append(copy.deepcopy({"outcome":outcome,"facts":facts,"diff":diff,"cues":cues,"diagnostics":diagnostics}))
  summary.append({"index":len(steps)-1,"tick":tick,"revision":revision,"state":copy.deepcopy(s),"next_due":pending[0]["event"]["due_tick"],
   "result":code or ("retry" if prior else "committed"),"fact_count":len(facts),"cue_count":len(cues),"delta_count":None if diff is None else len(diff["changes"])})
 return {"format_version":1,"initial_core":initial_core,"initial_protocol":initial_protocol,"trace":{"header":header,"steps":steps}},pubs,summary

